import {SURFACE_SPAN,naturalForm,clipSurface,contains,isTrim,validForm,span} from './nail-form.js';
import {imprints,isTransfer,validTransfer,hasBase} from './transfer.js';
// Local, replayable paint actions. One gesture is one coat, including jelly.
export const SIZE=512;
export const SURFACE_HEIGHT=SIZE*SURFACE_SPAN;
const NATURAL=naturalForm();
export const palette=[['Tomato','#ba2e1f'],['Oxblood','#4d1524'],['Ink','#171918'],['Cream','#e8ddc3'],['Milk','#f5efe3'],['Ballet','#d8a7ac'],['Cobalt','#2343af'],['Moss','#626847'],['Espresso','#4a3028'],['Silver','#b4b8b3']].map(([name,color],number)=>({name,color,number:number+1}));
export const materials=['cream','jelly','pearl','chrome','glitter','magnetic','matte','gloss'];
export const paintTools=['brush','liner','dot','fan','pick','erase'];
export const toolNames=[...paintTools,'stamp','extend'];
export const objects=['star','spark','dot','heart','pearl'];
export function canvas(){const c=document.createElement('canvas');c.width=SIZE;c.height=SURFACE_HEIGHT;return c;}
function copy(c){const d=canvas();d.getContext('2d').drawImage(c,0,0);return d;}
export function createSurface(){const paint=canvas(),finish=canvas(),detail=canvas();return {canvas:paint,ctx:paint.getContext('2d',{willReadFrequently:true}),finish,fctx:finish.getContext('2d'),detail,dctx:detail.getContext('2d'),particles:[],objects:[]};}
export function startLayer(n,a){const result={paint:copy(n.canvas),finish:copy(n.finish),detail:copy(n.detail),layer:canvas(),mask:canvas(),ink:canvas(),particles:n.particles.slice(),objects:n.objects.slice(),deposits:[],count:0,action:a};if(a.tool!=='erase')for(const c of [result.layer,result.mask,result.ink]){const ctx=c.getContext('2d');clipSurface(ctx,a.surface||NATURAL);ctx.beginPath();ctx.rect(0,0,SIZE,SIZE*span(a.surface));ctx.clip();}return result;}
function random(seed){let x=seed|0;return ()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return (x>>>0)/4294967296;};}
function footprint(ctx,p,tool,color,soft=false){ctx.save();ctx.fillStyle=color;const rx=p.r*(p.sx||1),ry=(tool==='brush'?p.r*.6:p.r)*(p.sy||1);if(soft){const g=ctx.createRadialGradient(p.x,p.y,p.r*.1,p.x,p.y,p.r);g.addColorStop(0,color);g.addColorStop(1,'transparent');ctx.fillStyle=g;}ctx.beginPath();ctx.ellipse(p.x,p.y,rx,ry,0,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawObject(ctx,p,a){ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.sx||1,p.sy||1);ctx.rotate(a.rotation||0);const r=p.r;ctx.fillStyle=a.pigment||palette[a.color].color;ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=Math.max(2,r*.12);ctx.lineJoin='round';ctx.beginPath();if(a.object==='star'||a.object==='spark'){const count=a.object==='star'?5:4;for(let k=0;k<count*2;k++){const angle=-Math.PI/2+k*Math.PI/count;const radius=k%2?r*.4:r;k?ctx.lineTo(Math.cos(angle)*radius,Math.sin(angle)*radius):ctx.moveTo(Math.cos(angle)*radius,Math.sin(angle)*radius);}ctx.closePath();ctx.fill();}else if(a.object==='heart'){ctx.moveTo(0,r*.85);ctx.bezierCurveTo(-r*1.7,-r*.25,-r*.65,-r*1.45,0,-r*.55);ctx.bezierCurveTo(r*.65,-r*1.45,r*1.7,-r*.25,0,r*.85);ctx.stroke();}else{ctx.arc(0,0,r*(a.object==='pearl'?.75:.55),0,Math.PI*2);if(a.object==='pearl'){ctx.fillStyle='#e5ddc6';ctx.strokeStyle='#aa9981';ctx.lineWidth=1.7;ctx.fill();ctx.stroke();ctx.beginPath();ctx.arc(-r*.22,-r*.24,r*.17,0,Math.PI*2);ctx.fillStyle='#fffaf0';}ctx.fill();}ctx.restore();}
export function addStamp(layer,p){const a=layer.action,paint=layer.layer.getContext('2d'),mask=layer.mask.getContext('2d'),ink=layer.ink.getContext('2d');const pigment=a.pigment||palette[a.color].color;const index=materials.indexOf(a.material);if(a.tool==='pick'){if(layer.count===0)drawObject(ink,p,a);layer.count++;return;}
paint.save();if(a.legacy)paint.globalAlpha=a.legacyClear?0:a.tool==='brush'?.30*(a.blend||1):.96;footprint(paint,p,a.tool,pigment,a.tool==='fan');paint.restore();footprint(mask,p,a.tool,`rgb(${(index+1)*28},0,0)`);
if(a.material==='glitter'&&a.tool!=='erase'){const rng=random((a.seed||1)+layer.count*1376312589);const count=Math.max(1,Math.round((a.tool==='fan'?4:a.tool==='dot'?10:3)*(a.density??1)));for(let i=0;i<count&&layer.deposits.length<600;i++){const angle=rng()*Math.PI*2,dist=Math.sqrt(rng())*p.r,px=p.x+Math.cos(angle)*dist*(p.sx||1),py=p.y+Math.sin(angle)*dist*(p.sy||1)*(a.tool==='brush'?.6:1);if(px<0||py<0||px>SIZE||py>SURFACE_HEIGHT)continue;const r=.9+rng()*2.3;ink.save();ink.translate(px,py);ink.rotate(rng()*Math.PI);ink.globalAlpha=.65+rng()*.35;ink.fillStyle=rng()>.48?'#f4e9c7':rng()>.45?pigment:'#b5aaa0';ink.fillRect(-r,-r*.6,r*2,r*1.2);ink.restore();layer.deposits.push({x:px,y:py,r});}}
layer.count++;}
export function applyLayer(n,layer){const a=layer.action;for(const [ctx,base] of [[n.ctx,layer.paint],[n.fctx,layer.finish],[n.dctx,layer.detail]]){ctx.clearRect(0,0,SIZE,SURFACE_HEIGHT);ctx.drawImage(base,0,0);}if(a.tool==='erase'){for(const ctx of [n.ctx,n.fctx,n.dctx]){ctx.save();ctx.globalCompositeOperation='destination-out';ctx.drawImage(layer.layer,0,0);ctx.restore();}const removed=o=>a.points.some(p=>Math.hypot(o.x-p.x,o.y-p.y)<p.r+o.r*.5);n.particles=layer.particles.filter(p=>!removed(p));n.objects=layer.objects.filter(o=>!removed(o));}else if(a.tool==='pick'){n.dctx.drawImage(layer.ink,0,0);n.objects=[...layer.objects,{...a.points[0],object:a.object}];}else{const opacity=a.legacy?1:a.material==='jelly'?.32:a.material==='glitter'?.075:a.tool==='liner'||a.tool==='dot'?.97:.83;n.ctx.save();n.ctx.globalAlpha=opacity*(a.opacity??1)*(a.tool==='fan'?.34*(a.density??1):1);n.ctx.drawImage(layer.layer,0,0);n.ctx.restore();n.fctx.drawImage(layer.mask,0,0);n.dctx.drawImage(layer.ink,0,0);n.particles=[...layer.particles,...layer.deposits].slice(-6000);}
}
// A transferred recipe is replayed into an isolated coat, so its erasures cannot
// erase the recipient. Points stay in UV space; footprint aspect preserves stroke shape.
const recipeCache=new WeakMap(),baseCache=new WeakMap();
export function renderImprint(recipe,options={}){const aspect=options.aspect||recipe.aspect,key=[aspect,!!options.withoutBase,!!options.onlyBase].join(':');let cache=recipeCache.get(recipe);if(!cache){cache=new Map();recipeCache.set(recipe,cache);}if(!cache.has(key)){const surface=createSurface();replay(surface,recipe.actions,{...options,aspect:recipe.aspect/aspect});cache.set(key,surface);}return cache.get(key);}
export function surfaceHasBase(n){if(!hasBase(n.actions))return false;const prior=baseCache.get(n);if(prior?.last===n.actions.at(-1)&&prior?.length===n.actions.length)return prior.value;const surface=createSurface();replay(surface,n.actions,{onlyBase:true});const pixels=surface.ctx.getImageData(0,0,SIZE,SURFACE_HEIGHT).data;let value=false;for(let i=3;i<pixels.length;i+=4){if(pixels[i]>4){value=true;break;}}baseCache.set(n,{last:n.actions.at(-1),length:n.actions.length,value});return value;}
export function applyTransfer(n,a,options={}){
 const recipe=imprints.get(a.imprintId);if(!recipe)return;
 if(options.onlyBase&&!a.includeBase)return;
 const layer=renderImprint(recipe,{withoutBase:options.withoutBase||!a.includeBase,onlyBase:options.onlyBase,aspect:a.aspect});
 for(const [ctx,source,soft] of [[n.ctx,layer.canvas,true],[n.fctx,layer.finish,false],[n.dctx,layer.detail,true]]){ctx.save();clipSurface(ctx,a.surface||NATURAL);ctx.translate(a.offset.x*SIZE,a.offset.y*SIZE*(a.span||1));if(a.mirror){ctx.translate(SIZE,0);ctx.scale(-1,1);}if(soft&&a.softness)ctx.filter='blur('+a.softness+'px)';ctx.drawImage(source,0,0,SIZE,SIZE*(recipe.span||1),0,0,SIZE,SIZE*(a.span||1));ctx.restore();}
 const map=p=>({...p,x:(a.mirror?SIZE-p.x:p.x)+a.offset.x*SIZE,y:p.y*(a.span||1)/(recipe.span||1)+a.offset.y*SIZE*(a.span||1)});
 n.particles.push(...layer.particles.map(map));n.objects.push(...layer.objects.map(map));
 n.particles=n.particles.slice(-6000);
}
export function replay(n,actions,options={}){for(const ctx of [n.ctx,n.fctx,n.dctx])ctx.clearRect(0,0,SIZE,SURFACE_HEIGHT);n.particles=[];n.objects=[];let initialBase=true;
 for(const a of actions){if(isTrim(a)){trimSurface(n,a.surface);continue;}if(isTransfer(a)){applyTransfer(n,a,options);initialBase=false;continue;}
 const base=initialBase&&['brush','fan'].includes(a.tool);if(!['brush','fan','erase'].includes(a.tool))initialBase=false;if(base&&options.withoutBase)continue;if(options.onlyBase&&!base&&a.tool!=='erase')continue;
 const layer=startLayer(n,a),sx=Math.sqrt(options.aspect||1);a.points.forEach(p=>addStamp(layer,{...p,sx,sy:1/sx}));applyLayer(n,layer);
 }
}
export function migrate(data){if(!data||![1,2,3,4,5,6,7].includes(data.v)||!Array.isArray(data.nails)||data.nails.length!==10)return null;if(data.v>=2)return data;const old=['#ba2e1f','#4d1524','#171918','#ece4ce','#a6aaa8','#183ab4','#bacb35','#ffffff'],map=[0,1,2,3,9,6,7,4];return {...data,v:2,colorIndex:map[data.colorIndex]??0,material:'cream',nails:data.nails.map(actions=>actions.map((a,i)=>({...a,legacy:true,legacyClear:a.color===7,pigment:old[a.color],color:map[a.color]??0,material:a.color===4?'chrome':a.color===7?'gloss':'cream',seed:i+1}))),object:'star'};}
export function validAction(a){if(a?.surface&&!validForm(a.surface))return false;if(isTrim(a))return validForm(a.surface);if(isTransfer(a))return validTransfer(a);return a&&[a.opacity,a.density].every(v=>v===undefined||(Number.isFinite(v)&&v>=.1&&v<=1))&&paintTools.includes(a.tool)&&materials.includes(a.material)&&Number.isInteger(a.color)&&a.color>=0&&a.color<palette.length&&(!a.pigment||/^#[0-9a-f]{6}$/i.test(a.pigment))&&Array.isArray(a.points)&&a.points.length<=20000&&a.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.r>0&&p.r<180)&& (a.tool!=='pick'||objects.includes(a.object));}

export function trimSurface(n,form){const mask=canvas(),ctx=mask.getContext('2d');clipSurface(ctx,form);ctx.fillStyle='#fff';ctx.fillRect(0,0,SIZE,SIZE*span(form));const pixels=ctx.getImageData(0,0,SIZE,SURFACE_HEIGHT);for(let i=3;i<pixels.data.length;i+=4)pixels.data[i]=pixels.data[i]?255:0;ctx.putImageData(pixels,0,0);for(const context of [n.ctx,n.fctx,n.dctx]){context.save();context.globalCompositeOperation='destination-in';context.drawImage(mask,0,0);context.restore();}n.particles=n.particles.filter(p=>contains(form,p.x/SIZE,p.y/SIZE));n.objects=n.objects.filter(p=>contains(form,p.x/SIZE,p.y/SIZE));}
